export function bermudaPensionSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !BERMUDA_PENSION_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid Bermuda pension figure variant');
  return snippets[kind + '-' + lang + '-' + (mobile ? 'mobile' : 'desktop')];
}
